// content_erp.js —— ERP（赛狐 Sellfox）页面内操作，照搬 automation/erp.py。
// 由 background 注入到 sellfox.com 的所有 frame；只有承载订单表(vxe)的那个 frame 会真正干活，
// 其余 frame 的 dispatch 返回 null，被 background 过滤掉。
// 每个 op 把过程日志 push 进 L，随结果一起返回，由 background 转发到 popup 实时显示。
window.__HWC_ERP = window.__HWC_ERP || (function () {
  const H = window.__HWC;
  const FILTER_TEMPLATE = "未取消等待发货";

  // 该 frame 是否承载订单业务视图？（有 vxe 表格 或 待处理/物流下单 相关 DOM）
  function isErpFrame() {
    return !!(document.querySelector(".vxe-table, .vxe-header--column") ||
              H.findByExactText("物流下单") ||
              H.qsa("*").some((e) => e.children.length === 0 && H.norm(e.innerText) === "待处理"));
  }

  function dismissNotifications() {
    try { H.qsa(".el-notification").forEach((e) => e.remove()); } catch (e) {}
  }

  // 等模板 popover 与 loading 遮罩都消失再操作。实测坑(2026-07-15)：选中筛选模板后，模板 popover
  // 残留 + 列表刷新 loading 遮罩，会让紧接着的渠道 input 点击弹不开渠道下拉（单例 popover 被占/
  // 遮罩拦点）——现象=模板成功那次渠道三次全未弹开、模板失败那次渠道反而能开（强相关）。
  const BLOCKER_SEL = ".el-popover, .select-menu, .search_more_temp_new, .el-loading-mask, .loading-indicator-overlay, .vxe-loading--wrapper";
  async function waitPageSettle(timeout = 6000) {
    await H.waitFor(() => !H.qsa(BLOCKER_SEL).some((p) => H.isVisible(p)), { timeout, interval: 300 });
  }
  function visibleBlockers() {
    return [...new Set(H.qsa(BLOCKER_SEL).filter((e) => H.isVisible(e))
      .map((e) => (typeof e.className === "string" ? e.className : "").split(" ")[0]).filter(Boolean))];
  }

  // 元素简描：标签+前3个class+placeholder+短文本。用于报错时说清「到底定位到了什么」。
  function describeEl(el) {
    if (!el) return "null";
    const cls = (typeof el.className === "string" ? el.className : "").trim().split(/\s+/).filter(Boolean).slice(0, 3).join(".");
    const ph = el.placeholder ? ` ph="${el.placeholder}"` : "";
    const txt = H.norm(el.innerText || "").slice(0, 24);
    return `<${el.tagName.toLowerCase()}${cls ? "." + cls : ""}${ph}>${txt ? ` "${txt}"` : ""}`;
  }
  // 输入框祖先链的首个 class（最多 5 层）——判断真正该点哪一层容器才能弹开下拉。
  function ancestorClasses(el, depth = 5) {
    const a = []; let p = el && el.parentElement;
    for (let i = 0; i < depth && p; i++) {
      const c = (typeof p.className === "string" ? p.className : "").trim().split(/\s+/)[0];
      if (c) a.push(c);
      p = p.parentElement;
    }
    return a;
  }
  // 渠道相关 DOM 现状快照。ERP 改版(placeholder/class 改了)时，一眼看出「渠道输入框」为何没命中。
  function channelDomSnapshot() {
    const inputs = [...new Set(H.qsa("input").filter(H.isVisible)
      .map((e) => e.placeholder || "(无placeholder)"))].slice(0, 25);
    const chanTexts = [...new Set(H.qsa("span, div, label, button")
      .filter((e) => H.isVisible(e) && e.children.length <= 2 && /渠道/.test(e.innerText || ""))
      .map((e) => H.norm(e.innerText)).filter(Boolean))].slice(0, 10);
    return { 可见input的placeholder: inputs, 含渠道字样的可见元素: chanTexts };
  }

